using System;using System.IO;using System.Linq;using System.Threading;using System.Diagnostics;using System.Collections.Generic;using System.Web.Script.Serialization;
class ResourceLiveProbe{static int Main(string[] args){var runtime=new AssistantRuntime(AppDomain.CurrentDomain.BaseDirectory);runtime.Config.Monitor.Quota.Enabled=false;var rows=new List<object>();try{for(int i=0;i<7;i++){var timer=Stopwatch.StartNew();var s=runtime.Poll().Sample;var row=new{utc=s.Utc,cpu=s.Cpu,memoryMiB=s.MemoryUsed*1024,gpu=s.Gpu,gpuSource=s.GpuState,pollMilliseconds=timer.ElapsedMilliseconds};rows.Add(row);Console.WriteLine(new JavaScriptSerializer().Serialize(row));Thread.Sleep(2000);}File.WriteAllText(Path.Combine(args[0],"live-resources.json"),new JavaScriptSerializer().Serialize(rows));return 0;}catch(Exception e){Console.WriteLine(e);return 1;}finally{runtime.Telemetry.Dispose();}}
}
